#include "stdafx.h"#include <rsuClipboard.h>void rsuTxtToClp( LPCSTR pszTxt ){  if( !OpenClipboard( NULL ))    return;  if( !EmptyClipboard() )  {    CloseClipboard();    return;  }  size_t L = strlen( pszTxt ) + 1;  HGLOBAL hData = GlobalAlloc( GMEM_MOVEABLE|GMEM_ZEROINIT, L );  if ( hData == NULL )  {    CloseClipboard();    return;  }  LPSTR pclpTxt = (LPSTR)GlobalLock( hData );  CopyMemory( pclpTxt, pszTxt, L );  GlobalUnlock( hData );  SetClipboardData( CF_TEXT, hData );  CloseClipboard();}